                    const dy = roundCentis(oy + startY + r * dotPitch - dotSize / 2);
                    parts.push(`<rect x="${dx}" y="${dy}" width="${dotSize}" height="${dotSize}" rx="0.2" fill="#E4E4E7" />`);
